import heapq

def match(orders):
    trades = []
    order_info = {}  # id -> dict(side, price, remaining, seq, active)
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0

    def clean_heap(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['remaining'] <= 0:
                heapq.heappop(heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info['active'] and info['remaining'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq_counter += 1
        my_seq = seq_counter

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            clean_heap(opp_heap)
            if not opp_heap:
                break
            top = opp_heap[0]
            resting_id = top[2]
            resting_info = order_info[resting_id]
            resting_price = resting_info['price']

            if typ == 'market':
                condition_ok = True
            else:
                if side == 'buy':
                    condition_ok = resting_price <= price
                else:
                    condition_ok = resting_price >= price

            if not condition_ok:
                break

            trade_qty = min(remaining, resting_info['remaining'])
            if side == 'buy':
                trades.append([oid, resting_id, resting_price, trade_qty])
            else:
                trades.append([resting_id, oid, resting_price, trade_qty])

            remaining -= trade_qty
            resting_info['remaining'] -= trade_qty

            if resting_info['remaining'] <= 0:
                resting_info['active'] = False
                heapq.heappop(opp_heap)
            # else keep position, don't pop (still at top, remains for next check)
            # but we need to check qty possibly not zero, so loop continues, will re-check same top
            # if remaining ==0 loop ends anyway.

        if typ == 'limit' and remaining > 0:
            order_info[oid] = {
                'side': side,
                'price': price,
                'remaining': remaining,
                'seq': my_seq,
                'active': True
            }
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, my_seq, oid))
            else:
                heapq.heappush(sell_heap, (price, my_seq, oid))
        else:
            if typ == 'limit':
                # fully filled, still record as inactive/filled for cancel lookups
                order_info[oid] = {
                    'side': side,
                    'price': price,
                    'remaining': 0,
                    'seq': my_seq,
                    'active': False
                }

    return trades

